ee:message.ee:set-payload:
%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
var papiError = if (errorBody is Object and errorBody.status?) errorBody else null
---
if (papiError != null) 
	papiError
else {
	"status": vars.httpStatus,
	"code": error.errorType.identifier default "CLIENT_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else 
					error.description default "Error en la solicitud al servicio de agendamientos."
	},
	"messageServer": error.description default "Error en la solicitud al servicio de agendamientos.",
	"cause": [
		{
			"origin": "customer-xapi-services",
			"message": "Error en llamada a appointment-papi-services: " ++ (error.errorType.identifier default "HTTP_CLIENT_ERROR")
		}
	]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
var papiError = if (errorBody is Object and errorBody.status?) errorBody else null
---
if (papiError != null) 
	papiError
else {
	"status": vars.httpStatus,
	"code": if (vars.httpStatus == 503) "SERVICE_UNAVAILABLE" 
			else if (vars.httpStatus == 504) "GATEWAY_TIMEOUT"
			else "PAPI_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else if (vars.httpStatus == 503)
					"El servicio de agendamiento no está disponible temporalmente. Por favor intente más tarde."
				   else if (vars.httpStatus == 504)
					"Tiempo de espera agotado al conectar con el servicio de agendamiento."
				   else 
					"Error en el servicio de agendamiento."
	},
	"messageServer": error.description default "Error en el servicio de agendamiento.",
	"cause": [
		{
			"origin": "appointment-xapi-services",
			"message": "Error en llamada a appointment-papi-services: " ++ (error.errorType.identifier default "HTTP_SERVER_ERROR")
		}
	]
}

%dw 2.0
output application/json
var isTimeout = (error.errorType.identifier default "") contains "TIMEOUT"
---
{
	"status": 503,
	"code": if (isTimeout) "TIMEOUT" else "SERVICE_UNAVAILABLE",
	"message": {
		"message": if (isTimeout) 
					"Tiempo de espera agotado al conectar con el servicio de agendamiento. Por favor intente nuevamente."
				   else 
					"No fue posible conectar con el servicio de agendamiento. Por favor intente más tarde."
	},
	"messageServer": error.description default "Error en el servicio de agendamiento.",
	"cause": [
		{
			"origin": "appointment-xapi-services",
			"message": "Error de conectividad con appointment-papi-services: " ++ (error.errorType.identifier default "CONNECTIVITY_ERROR")
		}
	]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
---
{
	"status": 500,
	"code": "INTERNAL_SERVER_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else 
					"Error inesperado en el servicio de agendamiento."
	},
	"messageServer": error.description default "Error en el servicio de agendamiento.",
	"cause": [
		{
			"origin": "appointment-xapi-services",
			"message": "Error inesperado en llamada a appointment-papi-services: " ++ (error.errorType.identifier default "UNKNOWN_ERROR")
		}
	]
}
